using FluentValidation;namespace Namaa.Application.PurchaseInvoices.Commands.AddPurchaseInvoiceItem;public sealed class AddPurchaseInvoiceItemCommandValidator:AbstractValidator<AddPurchaseInvoiceItemCommand>{public AddPurchaseInvoiceItemCommandValidator(){RuleFor(x=>x.PurchaseInvoiceId).GreaterThan(0);RuleFor(x=>x.Description).NotEmpty().MaximumLength(500);RuleFor(x=>x.Quantity).GreaterThan(0);RuleFor(x=>x.UnitPrice).GreaterThanOrEqualTo(0);RuleFor(x=>x.DiscountAmount).GreaterThanOrEqualTo(0);RuleFor(x=>x.TaxAmount).GreaterThanOrEqualTo(0);}}
